/// <summary>
/// PurchFormletterParmDataInvoice extension
/// </summary>
[ExtensionOf(classStr(PurchFormletterParmDataInvoice))]
final class METPurchFormletterParmDataInvoice_Extension
{
    public DocumentDate metDocumentDate;

}

Method.Source:
    /// <summary>
    /// CoC extension to initialise invoice date from the packing slip if the parameter to default is enabled
    /// </summary>
    /// <param name = "_parmTable">The <c>VendDocumentTableMap</c>.</param>
    /// <param name = "_purchLine">The purchase line.</param>
    /// <param name = "_purchTable">The purchase header.</param>
    /// <param name = "_tableRefId">The vendor invoice table reference.</param>
    /// <param name = "_hold">Hold on the vendor invoice.</param>
    /// <param name = "_notApproved">Is vendor invoice approved.</param>
    /// <param name = "_purchSummaryFormLetterId">The invoice number.</param>
    /// <param name = "_postingProfile">Vendor posting profile.</param>
    /// <param name = "_inventProfileType">Inventory profile type.</param>
    /// <returns>The initialized <c>VendDocumentTableMap</c>.</returns>
    protected VendDocumentTableMap initializeParmTable(
        VendDocumentTableMap  _parmTable,
        PurchLine             _purchLine,
        PurchTable            _purchTable,
        TradeLineRefId        _tableRefId,
        boolean               _hold,
        boolean               _notApproved,
        Num                   _purchSummaryFormLetterId,
        VendPostingProfile    _postingProfile,
        InventProfileType_RU  _inventProfileType
       )
    {
        VendDocumentTableMap metParmTable = next initializeParmTable(_parmTable, _purchLine, _purchTable, _tableRefId, 
                                                                    _hold, _notApproved, _purchSummaryFormLetterId, _postingProfile, 
                                                                    _inventProfileType);

        if(VendParameters::find().METDefaultInvDate)
        {
            if(this.parmMETDocumentDate())
            {
                metParmTable.DocumentDate = this.parmMETDocumentDate();
            }
            else
            {
                VendPackingSlipJour     metVendPackingSlipJour;
                VendPackingSlipTrans    metVendPackingSlipTrans;

                select firstonly DeliveryDate from metVendPackingSlipJour
                        order by DeliveryDate asc
                        where metVendPackingSlipJour.PurchId == _purchTable.PurchId
                    exists join metVendPackingSlipTrans
                        where   metVendPackingSlipTrans.VendPackingSlipJour == metVendPackingSlipJour.RecId &&
                                !metVendPackingSlipTrans.FullyMatched;

                if(metVendPackingSlipJour)
                {
                    metParmTable.DocumentDate = metVendPackingSlipJour.DeliveryDate;
                }
            }
        }

        return metParmTable;
    }

    /// <summary>
    /// MET method to initialise the document date from the receipts
    /// </summary>
    /// <param name = "_purchLine">Purchase order line</param>
    /// <param name = "_vendPackingSlipTrans">Packing slip line</param>
    /// <returns>Packing slip line</returns>
    [SuppressBPWarning('BPCheckParametersModified', 'Parameter required for Coc return')]
    protected VendPackingSlipTrans initVendPackingSlipTrans(PurchLine _purchLine, VendPackingSlipTrans _vendPackingSlipTrans)
    {
        _vendPackingSlipTrans = next initVendPackingSlipTrans(_purchLine, _vendPackingSlipTrans);

        //check if parm has been set in the previous loop run
        if(this.parmMETDocumentDate())
        {
            if(_vendPackingSlipTrans.vendPackingslipJour().DeliveryDate < this.parmMETDocumentDate())
            {
                this.parmMETDocumentDate(_vendPackingSlipTrans.vendPackingslipJour().DeliveryDate);
            }
        }
        else
        {
            this.parmMETDocumentDate(_vendPackingSlipTrans.vendPackingslipJour().DeliveryDate);
        }

        return _vendPackingSlipTrans;
    }

/// <summary>
/// parm the document date from the receipts
/// </summary>
/// <param name = "_documentDate">Document/invoice date</param>
/// <returns>Document date</returns>
public DocumentDate parmMETDocumentDate(DocumentDate _documentDate = metDocumentDate)
{
    metDocumentDate = _documentDate;
    return metDocumentDate;
}

    /// <summary>
    /// Extension method to update the vendor invoice info lines data.
    /// </summary>
    protected void createParmLinesAndTable()
    {
        next createParmLinesAndTable();

        VendInvoiceInfoTable vendInvoiceInfoTableChargeThrough;

        if (this.parmCallerTable().TableId == tableNum(VendInvoiceInfoTable))
        {
            vendInvoiceInfoTableChargeThrough = this.parmCallerTable();
        }

        ttsbegin;
        VendInvoiceInfoTable vendInvoiceInfoTableSkipInv = VendInvoiceInfoTable::findRecId(vendInvoiceInfoTableChargeThrough.RecId, true);

        if (vendInvoiceInfoTableSkipInv.METCrossDock || vendInvoiceInfoTableSkipInv.METChargeThrough || vendInvoiceInfoTableSkipInv.isLandedCostEnabled())
        {
            vendInvoiceInfoTableSkipInv.METSkipInvoiceMatching = NoYes::Yes;
        }
        else
        {
            vendInvoiceInfoTableSkipInv.METSkipInvoiceMatching = NoYes::No;
        }
        vendInvoiceInfoTableSkipInv.update();
        ttscommit;

        if (METVendParameters::find().EnableMetcashMatchingLogic && !vendInvoiceInfoTableChargeThrough.skipCustomInvoiceMatching() && !vendInvoiceInfoTableChargeThrough.isLandedCostEnabled())
        {
            ParmId currentParmId = this.parmId();

            VendInvoiceInfoLine vendInvoiceInfoLine;
            Query query = chooseLines.query();

            // If the PO datasource is disabled, return as no new lines will be created
            if ((query.dataSourceTable(tableNum(PurchTable)) && !query.dataSourceTable(tableNum(PurchTable)).enabled())||
            (this.parmCallerTable().TableId == tableNum(VendInvoiceInfoTable) && datasourceRecordsPacked))
            {
                return;
            }

            if (!this.allowSetBasedLogic())
            {
                return;
            }

            VendPackingSlipTrans vendPackingSlipTrans;
            VendPackingSlipJour vendPackingSlipJour;
            VendInvoiceInfoSubLine vendInvoiceInfoSubLine;
            PurchLine purchLine;

            ttsbegin;
            while select forupdate vendInvoiceInfoLine
                join RecId from VendInvoiceInfoSubLine
                    where vendInvoiceInfoLine.RecId == VendInvoiceInfoSubLine.LineRefRecId
                    && vendInvoiceInfoLine.ParmId != ''
                    && vendInvoiceInfoLine.ParmId == currentParmId
                    && VendInvoiceInfoSubLine.JournalRefTableId == tableNum(VendPackingSlipTrans)
                join Qty, PdsCWQty, ValueMST from  vendPackingSlipTrans 
                    order by vendPackingSlipTrans.DeliveryDate, vendPackingSlipTrans.LineNum, vendPackingSlipTrans.PackingSlipId asc
                    where VendInvoiceInfoSubLine.JournalRefRecId == vendPackingSlipTrans.RecId
                join RecId from vendPackingSlipJour
                    where vendPackingSlipTrans.VendPackingSlipJour == vendPackingSlipJour.RecId
                join PurchPrice from purchLine
                    where purchLine.InventTransId == vendPackingSlipTrans.InventTransId
                    && !purchLine.IsDeleted
            {
                vendInvoiceInfoLine.METReceiptedQuantity = vendPackingSlipTrans.Qty;
                vendInvoiceInfoLine.METReceiptedUnit = purchLine.PurchPrice;
                vendInvoiceInfoLine.METReceiptedCWQuantity = vendPackingSlipTrans.PdsCWQty;
                vendInvoiceInfoLine.METReceiptedLineNetAmount = vendPackingSlipTrans.ValueMST;
                vendInvoiceInfoLine.update();
            }
            ttscommit;
        }
    }
